[CmdletBinding()]
param(
    [string]$SolutionRoot
)

$ErrorActionPreference = 'Stop'

if ([string]::IsNullOrWhiteSpace($SolutionRoot)) {
    if ($PSScriptRoot) {
        $SolutionRoot = $PSScriptRoot
    }
    elseif ($MyInvocation.MyCommand.Path) {
        $SolutionRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
    }
    else {
        $SolutionRoot = (Get-Location).Path
    }
}

if (-not (Test-Path (Join-Path $SolutionRoot 'BookRunner.sln'))) {
    Write-Warning "BookRunner.sln '$SolutionRoot' altinda bulunamadi. Bu betigi BookRunner.sln ile ayni klasore koyup oradan calistirin, ya da -SolutionRoot parametresiyle dogru yolu verin."
}

$files = @(
    @{ Path = 'sql/02_BookRunner_Schema.sql'; Content = '' }
    @{ Path = 'src/BookRunner.Api/Authorization/BookRunnerClaimsTransformation.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Api/appsettings.json'; Content = '' }
    @{ Path = 'src/BookRunner.Application/Abstractions/IPersonnelDirectoryService.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Domain/Entities/RoleMapping.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/DependencyInjection.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Identity/RoleOptions.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Persistence/Configurations/DirectoryConfigurations.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Persistence/DatabaseInitializer.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Persistence/Migrations/20260827115149_InitialCreate.Designer.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Persistence/Migrations/20260827115149_InitialCreate.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Persistence/Migrations/BookRunnerDbContextModelSnapshot.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Personnel/PersonnelDirectoryOptions.cs'; Content = '' }
    @{ Path = 'src/BookRunner.Infrastructure/Personnel/PersonnelDirectoryService.cs'; Content = '' }
)

foreach ($f in $files) {
    $target = Join-Path $SolutionRoot $f.Path
    $dir = Split-Path $target -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [Convert]::FromBase64String($f.Content)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host "Yazildi: $($f.Path)"
}

Write-Host ''
Write-Host 'Tamamlandi. Simdi:'
Write-Host '  1) sql/02_BookRunner_Schema.sql dosyasini SQL Server''da (SSMS veya sqlcmd ile) calistirin'
Write-Host '  2) Visual Studio''da solutionu yeniden derleyin (Rebuild)'
Write-Host '  3) appsettings.json icindeki PersonnelDirectory ve Authorization:TeamRoleMappings ayarlarinizi kontrol edin'
